  ('db4c2db8-e6c9-56ae-b5e1-c15053eebb65', '22222222-2222-2222-2222-22222222221c', 'short', '斜率：倾斜角的正切值称为斜率，记𝑘= tan𝛼= 对边 邻边, (𝛼≠ π', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 44, true, 171, null),
  ('3b39e43f-af46-546f-b789-701a1376be7a', '22222222-2222-2222-2222-22222222221c', 'short', '.', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 44, true, 172, null),
  ('23fbe147-6a67-5445-8213-dc8543ff2ac1', '22222222-2222-2222-2222-22222222221c', 'short', '两点斜率公式：设直线𝑙上有两个点𝑃1(𝑥1, 𝑦1)与𝑃2(𝑥2, 𝑦2)，则𝑘= 𝑦2−𝑦1 𝑥2−𝑥1， 其中𝑥1 ≠𝑥2.', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 44, true, 173, null),
  ('0f6aa595-1990-50a9-b4cf-a67484ffccf9', '22222222-2222-2222-2222-22222222221c', 'short', '直线方程', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 44, true, 174, null),
  ('5e72d2eb-e60c-5990-bea5-dc33e3e36785', '22222222-2222-2222-2222-22222222221c', 'short', '点斜式：过点𝑃(𝑥0, 𝑦0)，斜率为𝑘的直线方程为𝑦−𝑦0 = 𝑘(𝑥−𝑥0)', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 44, true, 175, null),
  ('695e8138-fc7d-5255-b37c-7e4e7ee7d616', '22222222-2222-2222-2222-22222222221c', 'short', '斜截式：斜率为𝑘，在𝑦轴上截距为𝑏（即过点𝑃0(0, 𝑏)）的直线方程为 𝑦= 𝑘𝑥+ 𝑏.', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 44, true, 176, null),
  ('a6f626b2-6218-5c43-8132-d08cab2ecf80', '22222222-2222-2222-2222-22222222221c', 'short', '点(𝑥0, 𝑦0)到直线𝑎𝑥+ 𝑏𝑦+ 𝑐= 0的距离𝑑= |𝑎𝑥0+𝑏𝑦0+𝑐| √𝑎2+𝑏2 .', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 44, true, 177, null),
  ('0a64e65f-3c8c-50ea-b506-77fb122c2e01', '22222222-2222-2222-2222-22222222221c', 'short', '直线𝑎𝑥+ 𝑏𝑦+ 𝑐1 = 0与直线𝑎𝑥+ 𝑏𝑦+ 𝑐2 = 0的距离𝑑= |𝑐1−𝑐2| √𝑎2+𝑏2.', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 44, true, 178, null),
  ('72a22206-8963-538d-b67f-18409095b28f', '22222222-2222-2222-2222-22222222221c', 'short', '圆方程：圆心(𝑥0, 𝑦0)，半径为𝑟的圆可表示为(𝑥−𝑥0)2 + (𝑦−𝑦0)2 = 𝑟2. 你的坚持，终将美好！ 18', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 44, true, 179, null),
  ('f9d33aee-86ce-50c1-938c-ba45a22659b3', '22222222-2222-2222-2222-22222222221c', 'short', '两条直线的位置关系（重合、平行、相交、垂直）', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 45, true, 180, null),
  ('9d70485c-2c54-5aac-a8b6-bb47e84c216d', '22222222-2222-2222-2222-22222222221c', 'short', '两条直线的位置关系（重合、平行、相交、垂直） 直线𝑙：𝑦= 𝑘𝑥+ 𝑏，圆𝑂：(𝑥−𝑥0)2 + (𝑦−𝑦0)2 = 𝑟2, 𝑑= |𝑘𝑥0−𝑦0+𝑏| √𝑘2+1 为圆心 (𝑥0, 𝑦0)到直线𝑙的距离. 你的坚持，终将美好！ 19', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 45, true, 181, null),
  ('be82f800-7186-52e6-ad6e-5ea8cb6c51b5', '22222222-2222-2222-2222-22222222221c', 'short', '圆与圆的关系 圆𝑂1：(𝑥−𝑥1)2 + (𝑦−𝑦1)2 = 𝑟1 2；圆𝑂2：(𝑥−𝑥2)2 + (𝑦−𝑦2)2 = 𝑟2 2； 不妨设𝑟1 > 𝑟2，𝑑为圆𝑂1与𝑂2的圆心距. 你的坚持，终将美好！ 20', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 46, true, 182, null),
  ('0e742a8f-4da8-53c8-bb13-273927dfd195', '22222222-2222-2222-2222-22222222221c', 'short', '点关于点对称的对称点 𝑃(𝑥, 𝑦)关于𝐴(𝑥0, 𝑦0)的对称点𝑃′(2𝑥0 −𝑥, 2𝑦0 −𝑦)的坐标.', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 47, true, 183, null),
  ('4e00126f-6928-5d8c-bb77-298b1fb02b76', '22222222-2222-2222-2222-22222222221c', 'short', '直线关于点对称的对称直线 直线𝑙：𝑎𝑥+ 𝑏𝑦+ 𝑐= 0关于点𝑃(𝑥0, 𝑦0)对称的直线𝑙′的方程是 𝑎(2𝑥0 −𝑥) + 𝑏(2𝑦0 −𝑦) + 𝑐= 0，即𝑎𝑥+ 𝑏𝑦−2𝑎𝑥0 −2𝑏𝑦0 −𝑐= 0.', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 47, true, 184, null),
